// Lógica do nó "Detectar mudanças" do fluxo "eLabFTW – E-mails por fase".
// Função pura: recebe os dados lidos da API e o estado guardado e devolve as ações.
// O gerador (gerar-fluxo.py) embute este arquivo no nó Code do n8n.

function detectarMudancas({ cfg, experimentos, recursos, grupos, usuarios, estado }) {
  const semSituacao = 'Sem situação';

  const registros = [
    ...experimentos
      .filter((r) => cfg.categoriasExperimentos.includes(r.category_title))
      .map((r) => ({ ...r, _tipo: 'experimento', _pagina: 'experiments.php' })),
    ...recursos
      .filter((r) => cfg.categoriasRecursos.includes(r.category_title))
      .map((r) => ({ ...r, _tipo: 'recurso', _pagina: 'database.php' })),
  ];

  const guardado = new Map(estado.filter((o) => o && o.chave).map((o) => [o.chave, o]));
  const emailDe = new Map(usuarios.filter((u) => u && u.userid !== undefined).map((u) => [String(u.userid), u]));
  const grupoPorId = new Map(grupos.filter((g) => g && g.id !== undefined).map((g) => [String(g.id), g]));

  const lerPermissao = (canread) => {
    if (!canread) return {};
    if (typeof canread === 'object') return canread;
    try { return JSON.parse(canread); } catch (e) { return {}; }
  };

  const equipeDo = (r) => {
    const perm = lerPermissao(r.canread);
    const gruposDoRegistro = (perm.teamgroups || []).map((id) => grupoPorId.get(String(id))).filter(Boolean);
    const ids = new Set();
    for (const g of gruposDoRegistro) for (const u of g.users || []) ids.add(String(u.userid));
    if (ids.size === 0 && r.userid !== undefined) ids.add(String(r.userid));
    const pessoas = [...ids].map((id) => emailDe.get(id)).filter((u) => u && u.email);
    return { nomesGrupos: gruposDoRegistro.map((g) => g.name), pessoas };
  };

  const memorizar = [];
  const mudancas = [];

  for (const r of registros) {
    const chave = `${r._tipo}:${r.id}`;
    const linha = {
      chave,
      tipo: r._tipo,
      registro_id: Number(r.id),
      titulo: String(r.title ?? ''),
      status_id: r.status === null || r.status === undefined ? '' : String(r.status),
      status: r.status_title || semSituacao,
    };
    const anterior = guardado.get(chave);
    if (!anterior) {
      memorizar.push(linha);
    } else if (String(anterior.status_id ?? '') !== linha.status_id) {
      mudancas.push({ r, linha, anterior: anterior.status || semSituacao });
    }
  }

  const prefixo = cfg.modoTeste ? '[TESTE] ' : '';
  const RODAPE = 'Aviso automático do eLabFTW do Modal. Dúvidas: pesquisa@modal.org.br.';
  const remetente = { nomeRemetente: 'PD&I Modal', responderPara: 'pesquisa@modal.org.br' };
  const testador = emailDe.get(String(cfg.usuarioTesteId));
  if (cfg.modoTeste && mudancas.length > 0 && !(testador && testador.email)) {
    throw new Error(`Modo de teste: usuário ${cfg.usuarioTesteId} sem e-mail legível pela API; nada foi enviado.`);
  }

  const saida = memorizar.map((linha) => ({ acao: 'memorizar', ...linha }));

  if (mudancas.length > cfg.limiteAvisosPorExecucao) {
    const alvo = emailDe.get(String(cfg.usuarioTesteId));
    if (!alvo || !alvo.email) throw new Error('Muitas mudanças de uma vez e sem destinatário para o alerta; nada foi enviado.');
    for (const m of mudancas) saida.push({ acao: 'memorizar', ...m.linha });
    saida.push({
      acao: 'alertar',
      ...remetente,
      para: alvo.email,
      assunto: `${prefixo}eLabFTW: ${mudancas.length} mudanças de situação de uma vez (avisos individuais suspensos)`,
      etiqueta: 'eLabFTW · Alerta',
      titulo: `${mudancas.length} mudanças de situação numa só consulta`,
      blocos: [
        { tipo: 'paragrafo', texto: `O limite é de ${cfg.limiteAvisosPorExecucao} por consulta. Os avisos individuais não foram enviados; as situações novas ficaram registradas.` },
        { tipo: 'lista', itens: mudancas.map((m) => `${m.r.category_title}: ${m.linha.titulo} (${m.anterior} → ${m.linha.status})`) },
      ],
      acaoRotulo: 'Abrir o eLabFTW',
      acaoUrl: cfg.urlPublica,
      rodape: RODAPE,
    });
    return saida;
  }

  for (const m of mudancas) {
    const { r, linha, anterior } = m;
    const { nomesGrupos, pessoas } = equipeDo(r);
    const reais = pessoas.map((u) => u.email);
    const para = cfg.modoTeste ? [testador.email] : reais;
    if (para.length === 0) {
      saida.push({ acao: 'memorizar', ...linha, semDestinatario: true });
      continue;
    }
    const link = `${cfg.urlPublica}/${r._pagina}?mode=view&id=${r.id}`;
    const projeto = nomesGrupos.length ? nomesGrupos.join(', ') : 'sem grupo de projeto';
    const nota = cfg.modoTeste
      ? `Modo de teste: este aviso iria para ${pessoas.map((u) => u.fullname).join(', ') || 'ninguém'}.`
      : '';
    saida.push({
      acao: 'avisar',
      ...linha,
      para: para.join(','),
      ...remetente,
      assunto: `${prefixo}eLabFTW: ${r.category_title} "${linha.titulo}" passou para ${linha.status}`,
      etiqueta: `eLabFTW · ${r.category_title}`,
      titulo: `"${linha.titulo}" passou para ${linha.status}`,
      blocos: [
        { tipo: 'paragrafo', texto: 'O registro mudou de situação:' },
        { tipo: 'mudanca', de: anterior, para: linha.status },
        { tipo: 'campos', itens: [
          { rotulo: 'Categoria', valor: r.category_title },
          { rotulo: 'Projeto', valor: projeto },
          { rotulo: 'Responsável pelo registro', valor: r.fullname || '—' },
        ] },
        ...(nota ? [{ tipo: 'aviso', tom: 'teste', texto: nota }] : []),
      ],
      acaoRotulo: 'Ver no eLabFTW',
      acaoUrl: link,
      rodape: RODAPE,
    });
  }

  return saida;
}


const dados = (nome) => $(nome).all().map((i) => i.json);
const saida = detectarMudancas({
  cfg: $('Configuração').first().json,
  experimentos: dados('Ler experimentos').filter((o) => o && o.id !== undefined),
  recursos: dados('Ler recursos').filter((o) => o && o.id !== undefined),
  grupos: dados('Ler grupos'),
  usuarios: dados('Ler usuários'),
  estado: dados('Ler situação guardada'),
});
return saida.map((json) => ({ json }));

